/* Model initialize function */
void SiMappedEngine_initialize(const char_T **rt_errorStatus, boolean_T
  *rt_stopRequested, RTWSolverInfo *rt_solverInfo, RT_MODEL_SiMappedEngine_T *
  const SiMappedEngine_M, B_SiMappedEngine_c_T *localB, DW_SiMappedEngine_f_T
  *localDW, X_SiMappedEngine_n_T *localX, rtwCAPI_ModelMappingInfo *rt_ParentMMI,
  const char_T *rt_ChildPath, int_T rt_ChildMMIIdx, int_T rt_CSTATEIdx)
{
  /* Registration code */

  /* initialize non-finites */
  rt_InitInfAndNaN(sizeof(real_T));

  /* initialize real-time model */
  (void) memset((void *)SiMappedEngine_M, 0,
                sizeof(RT_MODEL_SiMappedEngine_T));

  /* initialize error status */
  rtmSetErrorStatusPointer(SiMappedEngine_M, rt_errorStatus);

  /* initialize stop requested flag */
  rtmSetStopRequestedPtr(SiMappedEngine_M, rt_stopRequested);

  /* initialize RTWSolverInfo */
  SiMappedEngine_M->solverInfo = (rt_solverInfo);

  /* Set the Timing fields to the appropriate data in the RTWSolverInfo */
  rtmSetSimTimeStepPointer(SiMappedEngine_M, rtsiGetSimTimeStepPtr
    (SiMappedEngine_M->solverInfo));
  SiMappedEngine_M->Timing.stepSize0 = (rtsiGetStepSize
    (SiMappedEngine_M->solverInfo));

  /* block I/O */
  (void) memset(((void *) localB), 0,
                sizeof(B_SiMappedEngine_c_T));

  /* states (dwork) */
  (void) memset((void *)localDW, 0,
                sizeof(DW_SiMappedEngine_f_T));

  /* Initialize DataMapInfo substructure containing ModelMap for C API */
  {
    SiMappedEngine_InitializeDataMapInfo(SiMappedEngine_M, localB, localX);
  }

  /* Initialize Parent model MMI */
  if ((rt_ParentMMI != (NULL)) && (rt_ChildPath != (NULL))) {
    rtwCAPI_SetChildMMI(*rt_ParentMMI, rt_ChildMMIIdx,
                        &(SiMappedEngine_M->DataMapInfo.mmi));
    rtwCAPI_SetPath(SiMappedEngine_M->DataMapInfo.mmi, rt_ChildPath);
    rtwCAPI_MMISetContStateStartIndex(SiMappedEngine_M->DataMapInfo.mmi,
      rt_CSTATEIdx);
  }
}
